# Task 5: Calculate the values needed for the six exploratory questions

date_range &lt;- NETFLIX_DATA |&gt;
  summarise(
    first_date = min(period_start, na.rm = TRUE),
    last_date = max(period_end, na.rm = TRUE)
  )

number_of_titles &lt;- NETFLIX_DATA |&gt;
  summarise(n = n_distinct(title))

bridgerton_hours &lt;- NETFLIX_DATA |&gt;
  filter(str_detect(title, regex("Bridgerton", ignore_case = TRUE))) |&gt;
  summarise(hours = sum(hours_viewed, na.rm = TRUE))

stranger_things_hours &lt;- NETFLIX_DATA |&gt;
  filter(str_detect(title, regex("Stranger Things", ignore_case = TRUE))) |&gt;
  filter_out(str_detect(title, regex("Beyond Stranger Things", ignore_case = TRUE))) |&gt;
  filter_out(str_detect(title, regex("Tales From", ignore_case = TRUE))) |&gt;
  filter_out(str_detect(title, regex("Stranger Things: Fireplace", ignore_case = TRUE))) |&gt;
  summarise(hours = sum(hours_viewed, na.rm = TRUE))

top_10_share_2026H1 &lt;- NETFLIX_DATA |&gt;
  filter(period == "2026H1") |&gt;
  arrange(desc(hours_viewed)) |&gt;
  mutate(rank = row_number()) |&gt;
  filter(rank &lt;= 10) |&gt;
  summarise(share = sum(hours_viewed, na.rm = TRUE) /
              sum(NETFLIX_DATA$hours_viewed[NETFLIX_DATA$period == "2026H1"],
                  na.rm = TRUE))

global_availability &lt;- NETFLIX_DATA |&gt;
  summarise(
    title_fraction = n_distinct(title[available_globally == TRUE]) /
      n_distinct(title),
    hours_fraction = sum(hours_viewed[available_globally == TRUE], na.rm = TRUE) /
      sum(hours_viewed, na.rm = TRUE)
  )

